 \newcommand{\root}[2][]{\,\sqrt[#1]{\,{#2}\,}\,}
 \newcommand{\totald}[3][]{\frac{\mathrm{d}^{#1} #2}{\mathrm{d} #3^{#1}}}
 \newcommand{\verts}[1]{\left\vert\,{#1}\,\right\vert}$
\begin{align}
\int_{0}^{\infty}{\expo{-x} - \expo{-2x} \over x}\,\dd x & =
\int_{0}^{\infty}\int_{1}^{2}\expo{-xt}\,\dd t\,\dd x =
\int_{1}^{2}\int_{0}^{\infty}\expo{-xt}\,\dd x\,\dd t =
\int_{1}^{2}{1 \over t}\,\dd t = \bbx{\ln\pars{2}}
\end{align} 
